fn export_csv(rows: &[(&str, u32)]) -> String {
    let mut csv = String::from("name,count\n");
    for (name, count) in rows {
        csv.push_str(&csv_field(name));
        csv.push(',');
        csv.push_str(&count.to_string());
        csv.push('\n');
    }
    csv
}

fn csv_field(value: &str) -> String {
    if value.contains([',', '"', '\n', '\r']) {
        format!("\"{}\"", value.replace('"', "\"\""))
    } else {
        value.to_owned()
    }
}

#[cfg(test)]
mod tests {
    use super::{csv_field, export_csv, TABLE};

    #[test]
    fn exports_table_with_header_and_rows() {
        assert_eq!(
            export_csv(&TABLE),
            "name,count\napples,3\npears,5\nplums,2\n"
        );
    }

    #[test]
    fn quotes_csv_fields_when_required() {
        assert_eq!(csv_field("plain"), "plain");
        assert_eq!(csv_field("two, words"), "\"two, words\"");
        assert_eq!(csv_field("a\"b"), "\"a\"\"b\"");
    }
}
